import random, sys, json, copy
sys.path.insert(0, '/workspace/submission'); sys.path.insert(0, '/workspace/tmp')
import para, algo, cmp_plan


def check(prof, fab, tag):
    plan = algo.compile_plan(prof, fab)
    r = algo.audit(prof, fab, plan)
    if r != {'valid': True}:
        print('FAIL self-audit not valid', tag)
        print(json.dumps(prof)); print(json.dumps(fab))
        return False
    cal = para.calibrate(prof)
    if cal['status'] != 'ok':
        a = algo.audit(prof, fab, {'status': 'inconsistent', 'cycle': cal['cycle']})
        b = algo.audit(prof, fab, {'status': 'ok'})
        if a != {'valid': True}:
            print('FAIL inconsistency certificate rejected', tag)
            return False
        if b != {'valid': False}:
            print('FAIL ok accepted for inconsistent profile', tag)
            return False
        # corrupt cycle
        cyc = cal['cycle']
        for mut in [ cyc[1:] if len(cyc) > 1 else [],
                     [cyc[0], cyc[0]] if cyc else [],
                     cyc[:-1] if len(cyc) > 1 else [] ]:
            r = algo.audit(prof, fab, {'status': 'inconsistent', 'cycle': mut})
            if r != {'valid': False}:
                print('FAIL cycle mutation accepted', tag, mut); return False
        return True
    # mutations of a feasible plan
    fails = []
    p = copy.deepcopy(plan)
    p['peaks_as'][0] = (p['peaks_as'][0] + 1) if p['peaks_as'][0] is not None else 0
    if algo.audit(prof, fab, p) != {'valid': False}: fails.append('peak')
    p = copy.deepcopy(plan)
    if p['guard_ns'] is not None:
        p['warmup_cycle'] = p['warmup_cycle'] + 1
        if algo.audit(prof, fab, p) != {'valid': False}: fails.append('warmup')
        p = copy.deepcopy(plan)
        B = p['bounds_as']
        done = False
        for i in range(len(B)):
            for j in range(len(B[i])):
                if B[i][j] is not None:
                    B[i][j] += 1; done = True; break
            if done: break
        if algo.audit(prof, fab, p) != {'valid': False}: fails.append('bound')
        p = copy.deepcopy(plan)
        A = p['age_rounds']
        done = False
        for i in range(len(A)):
            for j in range(len(A[i])):
                if A[i][j] is not None:
                    A[i][j] += 1; done = True; break
            if done: break
        if algo.audit(prof, fab, p) != {'valid': False}: fails.append('age')
        p = copy.deepcopy(plan)
        pr = p['pred']
        done = False
        for i in range(len(pr)):
            for j in range(len(pr[i])):
                if isinstance(pr[i][j], list):
                    pr[i][j][0] = (pr[i][j][0] + 1) % (fab['n'] * plan['period_rounds']); done = True; break
            if done: break
        if algo.audit(prof, fab, p) != {'valid': False}: fails.append('predvertex')
        p = copy.deepcopy(plan)
        pr = p['pred']
        done = False
        for i in range(len(pr)):
            for j in range(len(pr[i])):
                if isinstance(pr[i][j], list):
                    pr[i][j][1] = pr[i][j][1] + 1; done = True; break
            if done: break
        if algo.audit(prof, fab, p) != {'valid': False}: fails.append('predkind')
        p = copy.deepcopy(plan)
        p['period_rounds'] += 1
        if algo.audit(prof, fab, p) != {'valid': False}: fails.append('period')
        p = copy.deepcopy(plan)
        p['guard_ns'] = None
        if algo.audit(prof, fab, p) != {'valid': False}: fails.append('guardnull')
    p = copy.deepcopy(plan)
    p['profile']['upper_ps'][0][0] = 5
    if algo.audit(prof, fab, p) != {'valid': False}: fails.append('upperdiag')
    p = copy.deepcopy(plan)
    if p['profile']['pred'][0][0] is None:
        p['profile']['pred'][0][0] = 10 ** 9
    if algo.audit(prof, fab, p) != {'valid': False}: fails.append('calpred')
    p = copy.deepcopy(plan)
    p['profile']['upper_ps'][0][-1] += 1 if len(p['profile']['upper_ps'][0]) > 1 else 0
    if algo.audit(prof, fab, p) != {'valid': False}: fails.append('uppercell')
    p = copy.deepcopy(plan)
    p['bounds_as'] = None
    if algo.audit(prof, fab, p) != {'valid': False}: fails.append('nullbounds')
    if fails:
        print('FAIL mutations accepted', tag, fails)
        print(json.dumps(prof)); print(json.dumps(fab))
        return False
    return True


def main(seed0, count):
    rng = random.Random(seed0)
    bad = 0
    n = 0
    for it in range(count):
        g = cmp_plan.gen(rng)
        if g is None: continue
        prof, fab = g
        n += 1
        if not check(prof, fab, it):
            bad += 1
            if bad >= 3: return
    print('audited', n, 'bad', bad)


if __name__ == '__main__':
    main(int(sys.argv[1]), int(sys.argv[2]))
